from src.models.base import BaseLLMProviderfrom src.schemas.schemas import LanguageDetectionfrom src.prompts import language_detection_user, language_detection_systemclass LanguageDetector:    def detect(self, text: str, llm_provider: BaseLLMProvider, model_name: str) -> LanguageDetection:        response = llm_provider.chat(            user_prompt=language_detection_user[model_name],            user_prompt_vars={                "text": text            },            system_prompt=language_detection_system[model_name],            structured_output=LanguageDetection        )        return response